-- Registered customers
-- dbo.Customers: SELECT
SELECT Id, Name, Email, CountryId
FROM dbo.Customers;

-- dbo.Customers: SELECT by key
SELECT Id, Name, Email, CountryId
FROM dbo.Customers
WHERE Id = @Id;

